            "마데카솔은 가벼운 상처, 찰과상, 화상, 습진성 피부염 등에 사용해요. 바른 후 피부 재생이 촉진되고 상처 부위의 염증이 줄면서 회복이 빨라지는 걸 느낄 수 있어요.\n\n스크래치나 가벼운 열상은 이틀 이내에 피부 표면이 아물기 시작하고, 1~2주 정도 꾸준히 사용하면 새살이 차오르는 게 보여요. 깊은 상처나 감염이 의심되는 경우에는 이 약만으로는 부족하고 피부과 치료가 필요해요.\n\n보습 효과도 있어서 건조해진 피부 장벽 회복에도 도움이 돼요. 아토피나 건성 피부의 가려움이 심한 부위에 얇게 발라주면 자극을 완화할 수 있어요.\n\n아직 감염 징후(붉어짐, 붓기, 열감, 진물)가 없는 초기 찰과상이나 화상에 가장 효과적이에요. 상처가 촉촉하게 유지될수록 세포 재생이 빨라요. 습윤 드레싱과 병행하면 치유 기간이 단축돼요. 증상이 나아 보여도 완전히 낫기 전 사용을 중단하면 세균이 다시 증식할 수 있어요.",
