            "아시클로버크림은 단순포진 바이러스 감염증에 쓰는 항바이러스 성분의 외용 크림이죠. 식약처 허가사항 기준으로 초기 및 재발성 생식기포진과 구순포진 두 가지 모두에 사용 범위가 잡혀 있어요.\n\n이 약은 외용으로만 사용하도록 정해져 있어요. 안과용은 아니에요. 각막이나 점막에 바르면 안 돼요. 피부 표면의 감염 부위에만 얇게 바르는 용도로 설계된 크림이에요.\n\n바를 때는 골무나 고무장갑을 낀 상태로 도포하는 게 원칙이고요. 손으로 직접 바르면 성분이 신체 다른 부위로 퍼지거나 타인에게 옮길 수 있기 때문이에요. 희석도 금지예요. 이 약을 다른 약물과 섞는 기제로 쓰지 않는 것도 지켜야 할 부분이죠.",
