            "네, 발뒤꿈치나 복사뼈 부위 각질이 두껍고 갈라진 상태라면 발라도 되는 제품이에요. 식약처 허가사항 기준으로 고령자의 건피증과 성인의 거친 피부, 발뒤꿈치·복사뼈 부위의 각화증에 사용하도록 정해져 있거든요. 나이가 들수록 피부 수분이 줄면서 각질이 하얗게 일어나는 증상, 겨울철에 발뒤꿈치가 굳고 갈라지는 증상 모두 이 범위에 들어가요. 제품에는 히알루론산과 알란토인이 함께 들어 있어서, 건조하고 갈라지기 쉬운 각질 부위에 수분감을 더해주는 방향으로 만들어졌고요.\n\n다만 허가받은 부위 밖에서는 쓰지 않는 게 원칙이에요. 얼굴이나 눈 주위, 점막, 상처나 염증이 있는 곳에는 사용하지 않도록 정해져 있어요. 발뒤꿈치나 팔꿈치처럼 각질이 두꺼운 부위 위주로만 발라야 해요. 15세 미만 소아는 애초에 사용 대상이 아니라는 점도 기억해두세요.",
