            "히아로겔의 주성분은 히알루론산나트륨이에요. 정식 명칭은 히아로겔(히알루론산나트륨)이고, 한미약품에서 만들어요. 품목번호는 200301797이죠.\n\n식약처 허가사항 기준으로 이 약은 치은점막이 상승된 히알루론산 농도를 필요로 하는 치은염, 잇몸출혈 같은 염증 상태, 그리고 스케일링·박리·발치 같은 외과적 처치 이후의 외상성 상태를 치료 목적으로 사용하도록 되어 있어요. 항생제나 진통제는 아니에요. 점막이 회복되는 동안 필요한 히알루론산을 국소적으로 보충해주는 겔 형태 연고예요. 15g 용량이에요. 한 번 구입하면 여러 번 나눠 바를 수 있어요.",
