          content: "더마틱스울트라겔의 주성분은 흉터 조직을 개선하는 성분이에요. 실리콘 성분이 포함된 제품은 흉터 조직에 수분을 공급하고 얇게 막을 형성해서 콜라겐 생성을 정상화시켜요. 헤파린, 알란토인, 양파 추출물(케파 오니온) 성분이 포함된 제품은 각각 혈액 응고 억제, 세포 재생 촉진, 항염 효과를 내요.\n\n수술 흉터나 화상 흉터, 켈로이드(흉터 조직이 과도하게 돋아나는 상태) 억제에 쓰이는 성분들이에요. 흉터를 완전히 없애는 건 현재 기술로는 불가능하고, 흉터의 색깔, 두께, 유연성을 개선하는 게 현실적인 목표예요.\n\n겔이나 크림 제형으로, 환부에 얇게 바르면 성분이 흉터 조직 내로 서서히 흡수되면서 작용해요.\n\n실리콘 계열 흉터 제품은 피부에 산소와 수분 투과성이 있는 막을 만들어요. 흉터 조직 내 수분이 유지되면 콜라겐 분해 효소가 활성화되어 두꺼운 흉터 조직이 점차 부드러워져요.",
