            "이 연고의 주성분은 덱사메타손이에요. 염증 반응을 빠르게 눌러주는 부신피질호르몬 계열 성분이에요. 치과구강용약으로 분류된 일반의약품이기도 해요. 이 약에는 유효성분이 1가지 들어있어요.\n\n제조사는 녹십자예요. 입안 점막에 국소적으로 작용하도록 만들어진 연고 제형이에요. 먹는 약이 아니라 바르는 약이에요. 그래서 전신으로 퍼지는 양은 적은 편이에요. 다만 스테로이드 성분인 만큼 장기간 사용하면 몸에 영향을 줄 수 있다는 점은 알아둬야 해요.\n\n식약처에 신고 절차로 등록된 제품이라 처방전 없이 약국에서 구매 가능해요. 감염 자체를 없애는 항생제나 항진균제와는 달라요. 이 연고는 염증과 통증을 가라앉히는 역할을 해요. 원인균을 직접 없애는 약이 아니라는 점은 구분해서 써야 해요.",
