            "자운고의 주성분은 당귀와 자초, 두 가지 생약이에요. 성분 수는 딱 2가지예요. 당귀는 흔히 보약재로 알려졌지만 외용으로는 피부 자극을 가라앉히는 데 쓰여요. 자초는 지치라는 식물의 뿌리로, 예로부터 상처나 피부염 부위에 발랐던 재료죠. 식약처 허가 정보에는 이 두 성분이 'Angelica Gigas Root/Lithospermum Root'로, 품목번호 198000042로 등록돼 있어요.\n\n한풍제약이 만든 한풍자운고는 이 두 성분을 연고 기제에 배합해서 환부를 덮고 진정시키는 방식으로 작용해요. 항생제나 스테로이드 성분이 들어간 연고와는 결이 다르거든요. 화학 성분에 거부감이 있는 분들이 대신 찾는 경우가 많아요. 품목류 코드는 02690, '기타의 외피용약'으로 분류돼요.\n\n일반의약품이라 약국에서 처방전 없이 살 수 있어요. 짙은 자색 연고예요. 옷이나 이불에 묻으면 착색돼서 잘 안 빠지니, 바를 때는 조심하세요. 품목번호 198000042 제품의 식약처 등록 정보에 이 착색 주의사항이 별도로 명시돼 있어요.",
