            "박테로신연고 사용법은 간단해요. 감염된 부위에 하루 2~3회, 소량만 얇게 발라주면 돼요. 식약처 허가사항 기준 10일 정도 바르는 게 정해진 용법이고, 필요하면 바른 자리를 거즈로 덮거나 밀봉해서 관리할 수도 있어요.\n\n단, 이 연고는 외용으로만 써야 해요. 눈이나 코 같은 점막엔 닿지 않게 주의하세요. 중심정맥관을 삽입하는 부위에도 쓰면 안 돼요. 크게 찢어지거나 심하게 손상된 피부에 오랫동안 계속 바르는 것도 피해야 해요.\n\n바른 뒤엔 반드시 손을 씻어주세요. 하루 2~3회씩 10일이면 스무 번에서 서른 번 정도 바르는 셈인데, 정해진 횟수보다 더 자주 바른다고 빨리 낫는 건 아니에요. 상처 부위가 넓거나 깊다면 자가 처치보다 병원 진료를 먼저 받는 게 순서예요.",
