            "식약처 허가사항엔 실온에서 보관하라고 나와 있어요. 직사광선과 습기는 피하세요. 뚜껑도 잘 닫아 두세요. 여름철 자동차 안처럼 온도가 많이 오르는 곳은 특히 피해야 해요.\n\n프로베네시드를 복용 중인 분은 이 크림을 쓰기 전에 의사나 약사와 상의하는 게 허가사항에 명시돼 있어요. 두 성분이 만나면 작용이 달라질 수 있기 때문이에요. 다른 약과 섞어서 쓰거나 다른 용기에 옮겨 담는 것도 하지 마세요. 품목번호로 등록된 허가 정보인 만큼, 정해진 보관법과 병용 주의사항을 지키는 게 효과를 제대로 보는 길이에요. 유통기한 지나면 바로 새 제품으로 바꾸세요.",
