            "하나씩 살펴볼게요. 태극아시클로버크림 사용법은 간단해요. 4시간 간격으로 하루 5회, 환부 피부에 얇게 발라주면 돼요. 치료는 5일간 이어가는 게 기본이고, 5일이 지나도 낫지 않으면 5일을 더 사용할 수 있어요. 식약처 허가사항에 명시된 표준 용법이라 임의로 횟수를 늘리거나 줄이면 안 돼요.\n\n바르기 전엔 손을 깨끗이 씻어야 해요. 다른 부위나 다른 사람에게 옮기지 않도록 골무나 고무장갑을 낀 상태로 바르는 게 안전하죠. 외용으로만 쓰는 약이에요. 눈이나 각막, 점막 부위엔 사용하면 안 돼요. 크림을 다른 약과 섞거나 희석해서 쓰는 것도 금지돼 있어요.\n\n용법과 용량을 벗어나지 않는 게 중요해요. 보관은 실온에서 하면 되고, 개봉 후에도 원래 용기 그대로 뚜껑을 잘 닫아 보관하는 게 좋아요.",
