            "성분은 테르비나핀염산염 1가지예요. 일반의약품이죠. 분류상 기생성 피부질환용제에 속하고, 신고 절차로 허가받은 외용 항진균제라는 점은 식약처 등록 정보에 그대로 나와 있어요. 제조는 한솔신약에서 맡고 있어요.\n\n적용 대상 균은 트리코피톤(Trichophyton)속에서만 4가지 종(T. rubrum, T. mentagrophytes, T. verrucosum, T. violaceum)이 잡히고, 마이크로스포룸 카니스(Microsporum canis) 1종과 표피사상균(Epidermophyton floccosum) 1종까지 더하면 피부사상균만 6종을 커버해요. 여기에 어루러기를 일으키는 말라세지아(Pityrosporum orbiculare) 1종과 칸디다증을 일으키는 칸디다균 1종까지 적용 범위에 들어가서, 무좀약 중에서도 커버하는 균 종류가 많은 편이에요. 다만 세균 감염이나 바이러스성 피부질환에는 작용하지 않고, 곰팡이·효모균 2가지 계열에만 쓰는 약이라는 점은 꼭 기억해두세요.",
