            "베이덤연고를 바른 뒤 과민 반응이 나타날 수 있어요. 식약처 허가사항에는 과민증상, 때때로 습진화, 피부 균열, 구진, 따끔거리는 느낌, 작열감, 인설이 생길 수 있다고 나와 있어요.\n\n드물게는 부종이나 오히려 건조화가 심해지는 경우도 보고돼 있어요. 이런 증상이 나타나면 즉시 사용을 멈추고 의사나 약사와 상의하는 게 우선이죠. 통증이나 열감, 홍조, 가려움 같은 반응도 나타날 수 있으니 처음 며칠은 피부 상태를 유심히 살펴보는 게 좋아요. 바르고 나서 따가운 느낌이 오래가면 그건 정상 반응이 아니에요. 넓은 부위에 한꺼번에 바르기보다 좁은 부위부터 시작해서 반응을 확인하는 방법도 있고요. 허가 기준으로 정리된 내용인 만큼, 증상이 반복되거나 오래가면 자가판단으로 계속 바르지 말고 약사와 다시 상의하는 편이 안전해요.",
