          title: "복합테르쿨크림, 무좀·완선에 효과 있을까요?",
          content:
            "네, 효과가 있어요. 무좀이나 완선처럼 피부사상균이 원인인 감염엔 복합테르쿨크림을 써요. 식약처 허가사항에도 무좀, 완선(사타구니백선), 백선이 적응증으로 명시돼 있어요. 발가락 사이가 짓무르고 가려운 무좀이든, 사타구니 주변이 붉어지는 완선이든 같은 크림으로 대응할 수 있어요.\n\n다만 모든 피부 트러블에 다 듣는 건 아니에요. 습진이나 짓무름, 갈라짐이 심한 상처는 대상이 아니에요. 손톱이나 두피처럼 흡수 경로가 다른 부위도 마찬가지고요.\n\n증상 부위가 넓거나 이미 곪은 상태라면, 자가 판단으로 계속 바르지 말고 바르기 전에 전문가와 먼저 확인하세요. 겹치는 다른 피부병까지 낫게 해주는 크림은 아니라는 점도 기억해두면 좋아요.",
