            "사용법은 하루 1회, 저녁에 바르는 게 원칙이에요. 얼굴과 몸통의 환부를 깨끗이 씻고 완전히 건조시킨 다음 얇게 펴 발라요. 손끝에 남은 잔여물은 옷깃에 묻기 전에 닦아내는 게 좋아요. 얼굴 전체(이마, 코, 턱, 양쪽 볼)에는 1회 펌핑이면 충분하고, 윗몸통(등 위쪽·어깨·가슴)에는 2회 펌핑 정도가 적당해요. 중간 등이나 아래 등까지 번졌다면 1회 펌핑을 추가로 써도 괜찮아요. 허가사항 사용법 항목에 나온 기준이에요.\n\n중요한 건 횟수예요. 더 바른다고 안 낫는다는 얘기예요. 사용량을 늘리거나 하루에 여러 번 바른다고 효과가 빨라지지 않거든요. 오히려 자극감과 발적만 커질 수 있어서, 정해진 1일 1회를 지키는 게 핵심이에요. 눈이나 입, 코 주변, 점막, 상처 부위에는 닿지 않도록 주의하고, 닿았다면 바로 따뜻한 물로 씻어내야 해요. 치료 초기부터 보습제를 함께 쓰는 게 권장되고, 이 부위에 왁싱이나 전기분해 제모, 화학적 제모제를 쓰는 건 피해야 해요. 운전이나 기계 조작에 영향을 준다는 보고는 식약처 자료상 따로 없어요.",
