            "멜라노사크림의 유효 성분은 히드로퀴논 4%예요. 멜라닌 색소가 만들어지는 과정을 억제해서 이미 생긴 침착 부위를 점점 표백하는 방식으로 작용한다고 식약처 허가 기준에 적혀 있어요.\n\n일반의약품 1종으로 분류돼 있고, 제형은 크림 30g 용량이라 환부에 얇게 펴 바르는 방식이에요. 효과가 서서히 나타나는 성분이라 2개월 정도 발라도 개선이 없으면 사용을 중단하라고 등록 정보에 안내돼 있어요. 양을 임의로 늘리면 안 돼요. 1일 1~2회로 정해진 용법을 지키는 게 우선이에요.\n\n동아제약이 신고 형태로 등록한 일반의약품 1개예요. 그래서 약국에서 바로 구매할 수 있어요. 다만 오래 쓰라고 만든 성분은 아니에요. 2개월을 기준으로 삼고, 정해진 기간 안에서만 쓰는 게 식약처 등록 정보의 취지예요.",
