            "반질크림은 요소(우레아) 100% 성분으로 손발바닥이 두꺼워지고 갈라지는 각피증에 발라요. 식약처 허가사항 기준으로는 진행성 지장각피증, 손·발바닥 각피증, 어린선, 노인성 건피증, 모공성 태선, 아토피피부까지 적응증으로 등록돼 있어요. 품목번호는 201600366이에요.\n\n이름은 다르지만 공통점은 있어요. 피부 각질층이 두껍고 건조해서 갈라지거나 거칠어진 상태라는 거예요. 겨울철 손발이 유독 거칠어지는 분, 나이가 들면서 정강이나 팔 피부가 하얗게 각질이 일어나는 분들이 자주 찾아요.\n\n주부습진 중에서도 건조한 유형에만 해당한다는 점은 기억해두는 게 좋아요. 진물이 나는 급성 습진이나 염증이 심한 상태라면 오히려 사용을 피해야 하거든요. 증상이 낯설다면 약사에게 먼저 물어보세요.",
