          content: "리쥬드비에크림의 주성분은 피부 색소 멜라닌 생성을 억제하는 성분이에요. 히드로퀴논(Hydroquinone), 나이아신아마이드, 코직산, 알부틴 등이 대표적이에요. 히드로퀴논은 멜라닌 합성에 필요한 타이로시나제 효소를 직접 억제해서 색소 침착을 빠르게 줄이는 강력한 성분이에요.\n\n기미, 주근깨, 일광흑자(검버섯), 여드름 후 색소 침착에 사용해요. 히드로퀴논 농도 2% 이하는 일반의약품으로 분류되고, 4% 이상은 의사 처방이 필요한 전문의약품이에요.\n\n첨가제로 에틸알코올, 스쿠알렌, 글리세린 등이 포함되어 크림의 보습력과 발림성을 높이고 있어요.\n\n히드로퀴논은 공기에 노출되면 산화되어 갈색이나 회색으로 변해요. 변색된 크림은 효력이 없고 오히려 피부를 자극할 수 있어요. 뚜껑을 꼭 닫아 공기 노출을 최소화하는 것이 성분 유지의 핵심이에요.",
