          content: "파머시안피디알엔크림은 피부 질환 개선을 돕는 외용제예요. 유효 성분이 피부에 흡수되어 환부에 직접 작용해요. 크림, 겔, 연고, 로션 등 다양한 제형이 있고, 제형에 따라 흡수 속도와 사용감이 달라요.\n\n연고 제형은 보습력이 높아 건조한 피부에 적합하고, 겔 제형은 수분감이 높아 빠르게 흡수되어 끈적임이 적어요. 크림은 연고와 겔의 중간 형태로 범용성이 높아요.\n\n첨가제로는 기제 성분(파라핀, 바셀린, 폴리에틸렌글리콜 등)과 보존제(파라벤, 벤질알코올)가 포함될 수 있어요. 성분 알레르기가 걱정된다면 처음 사용 시 팔 안쪽에 테스트해보는 게 안전해요.\n\n외용제 선택 시 연고와 크림 제형의 차이를 알아두는 게 좋아요. 연고는 유분이 많아 보습력이 높고 각질이 두꺼운 부위에 적합해요. 크림은 유수 혼합 형태로 흡수가 빠르고 끈적임이 적어요. 겔은 수분 기반으로 가장 빨리 흡수돼요.",
