          content:
            "디판큐어크림은 벌레 물린 데, 가려움, 일광 화상 뒤에 생기는 피부 반응처럼 알레르기성이면서 세균 감염은 아닌 국소 염증에 쓰는 크림이에요. 식약처 허가 적응증에 이 세 가지가 그대로 명시돼 있어요.\n\n핵심은 '비감염성'이라는 조건이에요. 세균이나 바이러스, 곰팡이가 원인인 피부 감염에는 이 크림을 쓰면 안 돼요. 모기나 벌레에 물려 붉게 부어오르고 가려운 정도라면 적응증에 맞아요. 하지만 물린 자리가 곪거나 진물이 나는 상태라면 얘기가 달라져요. 세균 감염 쪽에 가까워서 이 크림의 적응증을 벗어나요.\n\n여드름이나 입 주위 피부염이 있는 부위, 상처가 깊게 갈라진 부위도 마찬가지예요. 증상이 허가 적응증에 딱 들어맞는 부위에만 쓰는 게 원칙이에요.",
