            "네오탄연고를 바른 자리에 발적이나 가려움, 화끈거림 같은 자극감이 나타날 수 있어요. 드물게는 구진이나 작은 물집, 피부 건조, 땀띠처럼 보이는 반응이 생기기도 하고요. 식약처 허가사항에 등록된 이상반응 목록이에요.\n\n증상이 오히려 심해지거나 새로운 발진, 부스럼, 농포성 피부염, 전염성농가진, 모낭염 같은 반응이 나타나면 사용을 멈추고 상담받는 게 맞아요. 알레르기성 접촉피부염이나 2차 감염이 오히려 새로 생기는 경우도 있어요. 바른 뒤 상처가 더 심해진다면 계속 바르지 말아야 해요.\n\n넓은 부위에 오래 바르면 성분이 전신으로 흡수되면서 드물게 부신 기능에 영향을 주거나 혈당 변화, 시력 이상이 나타날 수 있다는 점도 알아두면 좋아요. 흔한 증상은 아니에요. 다만 평소와 다른 변화가 느껴지면 가볍게 넘기지 않는 편이 안전해요.",
