          content: "헤파겔의 주성분은 헤파린나트륨(Heparin Sodium)이에요. 헤파린은 원래 혈액 응고를 막는 항응고제로 잘 알려져 있지만, 외용 겔로 피부에 바르면 피하 조직에 작용해서 혈종(멍의 원인이 되는 피하 출혈 덩어리)을 분해·흡수시키고 부종을 가라앉혀요.\n\n헤파린이 피부를 통해 흡수되면 피하 모세혈관에서 혈전 형성을 억제하고, 이미 생긴 혈종의 흡수를 촉진해요. 타박상 직후 피부 아래에 고인 혈액이 빠르게 흡수되면서 멍이 빨리 옅어지는 거예요.\n\n한림제약에서 제조하는 외용 겔 제형이에요. 겔 기제는 피부에 빠르게 흡수되고 끈적임이 적어 일상에서 편하게 사용할 수 있어요.",
