          content: "헤파겔은 타박상으로 생긴 멍, 부종, 혈종 완화에 사용하는 외용 겔이에요. 근육통, 타박상, 혈전성 정맥염(혈관 내 혈전이 생겨 염증이 생기는 상태)에도 적용돼요.\n\n멍이 드는 원리는 이렇게 돼요. 타박상으로 피하 모세혈관이 터지면 혈액이 피부 아래에 고이면서 멍이 생겨요. 헤파린이 이 혈종의 응고를 억제하고 자연 흡수를 도와주면서 멍이 빨리 사라지게 해요.\n\n부종(부기)이 심한 타박상에도 헤파린의 항염 효과로 부기가 가라앉아요. 혈전성 정맥염처럼 피부 아래 혈관에 혈전이 생긴 경우에도 사용할 수 있어요. 단, 심부정맥혈전증처럼 깊은 혈관 문제는 전문의 진료가 필요해요.",
