          "스웨트롤은 성인 기준 하루 1회, 1매를 사용해요. 눈과 코, 입을 제외한 얼굴 환부에 가볍게 5회 정도 문지르면 끝이에요. 바르기 전엔 환부를 깨끗이 씻어야 해요. 그리고 충분히 말려야 흡수가 고르게 돼요.\n\n중요한 건 그다음이에요. 적용한 뒤 4시간 이내에는 환부를 씻지 말아야 해요. 그래야 성분이 제 역할을 할 수 있어요. 씻는 타이밍만 지켜도 절반은 성공이에요. 눈이나 코, 입 점막에는 절대 닿지 않게 조심하세요. 손상되거나 최근에 면도한 피부에도 바르면 안 돼요.\n\n콘택트렌즈를 쓴다면 순서를 지켜야 해요. 렌즈부터 착용한 뒤 이 약을 바르거나, 바른 뒤엔 손을 깨끗이 씻고 나서 렌즈를 껴야 해요. 첨부문서 적용상 주의사항 3항에 나온 순서예요. 깜빡했다고 여러 매를 겹쳐 쓰면 안 돼요. 정해진 1매, 하루 1회, 5회 문지르기 원칙만 지키면 돼요. 품목번호 201308277 첨부문서 기준 사용법이에요.",
