          "가장 흔하게 나타나는 부작용은 바른 부위가 일시적으로 자극감이 들거나 붉어지는 증상이에요. 매우 흔한 편이에요. 처음 며칠은 이런 반응이 있을 수 있다고 생각하고 지켜보는 게 좋아요. 드물게는 피부염을 포함한 과민반응, 통증, 가려움증, 홍반, 발진, 피부 작열감(화끈거림) 같은 증상이 허가사항에 명시돼 있어요.\n\n이런 증상이 보이면 사용을 즉시 중단하세요. 의사나 약사와 상의해야 해요. 특히 작열감은 이 약이 물과 반응해 염산을 만들어내는 특성과 관련이 있어서, 바르기 전 피부를 충분히 말리지 않았을 때 더 잘 생기는 편이에요. 그래서 건조 여부를 매번 확인하는 습관이 부작용을 줄이는 실질적인 방법이 돼요. 과민증이 있는 사람은 처음부터 이 약을 사용하지 않는 게 원칙이고요. 눈이나 콧구멍, 입 같은 점막에 우발적으로 닿았을 때도 물로 충분히 씻어내는 대응이 필요해요.",
