        content: "성인과 만 2세 이상 소아는 흉터 및 주변 피부에 1일 수회 적당량을 바르고 가볍게 마사지해요. 상처가 완전히 아물어 딱지가 없어진 뒤부터 시작하세요. 상처에 아직 분비물이 있거나 딱지가 남아 있으면 쓰면 안 돼요.\n\n비후성 흉터(두꺼운 흉터)는 전날 밤 두껍게 바르고 붕대로 고정해서 하루 저녁 동안 적용하는 방법도 있어요. 이 방법은 성인에게만 권장해요. 어린이, 특히 영아에게는 붕대 고정 방식이 적절하지 않아요. 겔을 바른 뒤 붕대를 너무 꽉 감으면 혈액 순환에 방해가 될 수 있어요.\n\n눈 주위와 점막에는 절대 바르지 마세요. 사용 후 흉터 부위가 햇볕이나 강한 열에 노출되지 않도록 주의해야 해요. 실외 활동이 많은 날은 자외선 차단 조치를 함께 하는 게 좋아요. 어린이에게 사용할 때는 반드시 보호자가 지도·감독해야 해요.",
