        content: "후시딘밴드대형5매의 핵심 성분은 퓨시드산나트륨(Fusidic Acid Sodium)이에요. 이 항생제는 포도구균, 연쇄구균, 코리네박테륨, 클로스트리듐 같은 세균의 단백질 합성을 억제해서 감염을 막아줘요. 동화약품(주)에서 제조하며, 후시딘연고와 동일한 항균 성분이 밴드 패드에 적용된 형태예요.\n\n일반 밴드와 가장 큰 차이점은 패드 자체에 항생제가 함유돼 있다는 거예요. 연고를 따로 바를 필요 없이 밴드를 붙이기만 하면 항균 효과를 얻을 수 있어요. 대형 사이즈라 무릎, 팔꿈치, 정강이처럼 면적이 넓은 상처에 적합해요.\n\n다만 녹농균(Pseudomonas aeruginosa)에는 퓨시드산이 효과가 없어요. 녹색 또는 청록색 고름이 나오면 녹농균 감염 가능성이 있으니 이 밴드 대신 의사 진료를 받으세요.",
