        content: "밴드를 붙이는 즉시 상처 보호 효과가 시작돼요. 항균 성분인 퓨시드산나트륨은 밴드 패드에서 서서히 방출되면서 상처 부위의 세균 증식을 억제해요. 포도구균, 연쇄구균, 코리네박테륨, 클로스트리듐으로 인한 감염을 예방하는 데 효과적이에요.\n\n농가진, 감염성습진양피부염, 모낭염, 종기, 화농성한선염 같은 피부 감염 질환에 사용할 수 있어요. 화상·외상·봉합창·식피창에 의한 2차 감염 예방에도 도움이 돼요. 심상성여드름(보통여드름)에도 허가 적응증이 있지만, 여드름 치료 목적이면 전문의 상담이 더 효과적이에요.\n\n1주 정도 사용해도 상처가 호전되지 않거나 오히려 악화되면 사용을 중단하고 의사에게 보여야 해요. 항생제 밴드는 경미한 상처의 감염 예방용이지 깊은 상처 치료제가 아니에요.",
