    h1: "후시딘밴드일반형5매 성분 효과 | 항생제밴드 사용법 부작용까지",
    metaDescription: "후시딘밴드일반형5매(퓨시드산나트륨) 사용법과 부작용. 일반 크기 항생제 밴드의 성분, 효과, 주의사항까지 정리했습니다.",
